#include <stdio.h>
#include <stdlib.h>

static int n;
static int *head, *to, *next_edge;

static int bfs(int root, int *dist, int *parent) {
    int *queue = (int *)malloc((size_t)n * sizeof(int));
    for (int i = 1; i <= n; i++) {
        dist[i] = -1;
        if (parent) parent[i] = -1;
    }

    int front = 0, back = 0;
    queue[back++] = root;
    dist[root] = 0;
    int farthest = root;

    while (front < back) {
        int u = queue[front++];
        if (dist[u] > dist[farthest]) farthest = u;

        for (int e = head[u]; e != -1; e = next_edge[e]) {
            int v = to[e];
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                if (parent) parent[v] = u;
                queue[back++] = v;
            }
        }
    }

    free(queue);
    return farthest;
}

static int count_side(int root, int blocked, int target,
                      int *stack_node, int *stack_parent, int *stack_depth) {
    int top = 0;
    stack_node[top] = root;
    stack_parent[top] = blocked;
    stack_depth[top++] = 0;

    int count = 0;
    while (top > 0) {
        --top;
        int u = stack_node[top];
        int p = stack_parent[top];
        int d = stack_depth[top];

        if (d == target) {
            count++;
            continue;
        }

        for (int e = head[u]; e != -1; e = next_edge[e]) {
            int v = to[e];
            if (v != p) {
                stack_node[top] = v;
                stack_parent[top] = u;
                stack_depth[top++] = d + 1;
            }
        }
    }
    return count;
}

