    int edge_count = 0;
    for (int i = 0; i < n - 1; i++) {
        int x, y;
        scanf("%d %d", &x, &y);

        to[edge_count] = y;
        next_edge[edge_count] = head[x];
        head[x] = edge_count++;

        to[edge_count] = x;
        next_edge[edge_count] = head[y];
        head[y] = edge_count++;
    }

    int *dist = (int *)malloc((size_t)(n + 1) * sizeof(int));
    int *parent = (int *)malloc((size_t)(n + 1) * sizeof(int));

    int a = bfs(1, dist, NULL);
    int b = bfs(a, dist, parent);
    int diameter = dist[b];

    int *stack_node = (int *)malloc((size_t)n * sizeof(int));
    int *stack_parent = (int *)malloc((size_t)n * sizeof(int));
    int *stack_depth = (int *)malloc((size_t)n * sizeof(int));

    long long ways = 0;

    if (diameter % 2 == 0) {
        int radius = diameter / 2;
        int center = b;
        for (int i = 0; i < radius; i++) center = parent[center];

        int *branch_count = (int *)calloc((size_t)(n + 1), sizeof(int));
        int top = 0;

        for (int e = head[center]; e != -1; e = next_edge[e]) {
            int v = to[e];
            stack_node[top] = v;
            stack_parent[top] = center;
            stack_depth[top] = 1;
            top++;
            /* The branch identifier is stored separately below. */
        }

        /* Traverse each branch and count vertices at distance radius. */
        for (int e = head[center]; e != -1; e = next_edge[e]) {
            int root = to[e];
            int branch_top = 0;
            stack_node[branch_top] = root;
            stack_parent[branch_top] = center;
            stack_depth[branch_top++] = 1;

            while (branch_top > 0) {
                --branch_top;
                int u = stack_node[branch_top];
                int p = stack_parent[branch_top];
                int d = stack_depth[branch_top];

                if (d == radius) {
                    branch_count[root]++;
                    continue;
                }

                for (int ee = head[u]; ee != -1; ee = next_edge[ee]) {
                    int v = to[ee];
                    if (v != p) {
                        stack_node[branch_top] = v;
                        stack_parent[branch_top] = u;
                        stack_depth[branch_top++] = d + 1;
                    }
                }
            }
        }

        long long seen = 0;
        for (int e = head[center]; e != -1; e = next_edge[e]) {
            int count = branch_count[to[e]];
            ways += seen * count;
            seen += count;
        }

        free(branch_count);
    } else {
        int radius = diameter / 2;
        int center_b = b;
        for (int i = 0; i < radius; i++) center_b = parent[center_b];
        int center_a = parent[center_b];

        int left_count = count_side(center_a, center_b, radius,
                                    stack_node, stack_parent, stack_depth);
        int right_count = count_side(center_b, center_a, radius,
                                     stack_node, stack_parent, stack_depth);
        ways = (long long)left_count * right_count;
    }

    printf("%d\n%lld\n", diameter + 1, ways);

    free(head);
    free(to);
    free(next_edge);
    free(dist);
    free(parent);
    free(stack_node);
    free(stack_parent);
    free(stack_depth);
    return 0;
}
